# Phase 10C: checkpointed mobile candidate routing and sparse coverage.
phase10C_run <- function(){
 suppressPackageStartupMessages({library(data.table);library(digest);library(Rcpp);library(Matrix)})
 started<-Sys.time();root<-normalizePath(file.path(Sys.getenv('USERPROFILE'),'Downloads','AI PREDICTION','Ghana_Diagnostic_Imaging_Research'),winslash='/',mustWork=TRUE)
 P<-function(...)file.path(root,...);hash<-function(x)vapply(x,function(f)digest(file=f,algo='sha256'),character(1),USE.NAMES=FALSE)
 old<-rbindlist(lapply(c('9A','9B1','9B2','10A','10B','8D','8C2','8B2'),function(s){m<-fread(P('12_Reproducibility',paste0('phase',s,'_output_checksum_manifest.csv')));q<-fread(P('03_Data_Audit',paste0('phase',s,'_quality_gate.csv')));stopifnot(nrow(m)>0,all(q$passed),all(hash(P(m$relative_path))==m$SHA256));cat('Phase',s,':',nrow(m),'checksums PASS\n');m[,.(relative_path,SHA256)]}))
 base<-P('04_Spatial_Analysis','National_Road_Network');out<-P('05_Travel_Time_Matrices','Phase10C_Mobile');dir.create(out,recursive=TRUE,showWarnings=FALSE)
 if(Sys.info()[['sysname']]=='Windows' && file.exists('C:/rtools45/usr/bin/make.exe'))Sys.setenv(PATH=paste('C:/rtools45/usr/bin','C:/rtools45/x86_64-w64-mingw32.static.posix/bin',Sys.getenv('PATH'),sep=';'),RTOOLS45_HOME='C:/rtools45')
 cpp<-file.path(base,'Routing_Engine','phase8D_engine.cpp');Rcpp::sourceCpp(cpp,env=environment())
 read<-function(folder,suffix)readRDS(file.path(base,folder,paste0('CORE_PRIMARY',suffix,'.rds')))
 a<-as.data.table(read('Directed_Graphs','_arcs'));v<-as.data.table(read('Directed_Graphs','_vertices'));cost<-as.data.table(read('Routing_Costs','_arc_travel_costs'));pat<-read('Routing_Engine','_routing_patterns')
 stopifnot(nrow(a)==7065687L,nrow(v)==3421445L,identical(as.integer(a$arc_id),seq_len(nrow(a))),identical(as.integer(cost$arc_id),as.integer(a$arc_id)),identical(as.integer(v$vertex_id),seq_len(nrow(v))),identical(pat$reverse_patterns,lapply(pat$forward_patterns,rev)))
 for(s in c('slow','baseline','favorable'))stopifnot(all(is.finite(cost[[paste0(s,'_seconds')]])&cost[[paste0(s,'_seconds')]]>0))
 stopifnot(all(cost$slow_seconds>=cost$baseline_seconds),all(cost$baseline_seconds>=cost$favorable_seconds))
 gr<-router_create(nrow(v),as.integer(a$to),as.integer(a$from),pat$reverse_patterns);gf<-router_create(nrow(v),as.integer(a$from),as.integer(a$to),pat$forward_patterns);rm(a);gc()
 dirs<-c(slow=P('05_Travel_Time_Matrices','Phase9B2_Sensitivity','M02'),baseline=P('05_Travel_Time_Matrices','Phase9B1_Core_Baseline'),favorable=P('05_Travel_Time_Matrices','Phase9B2_Sensitivity','M03'))
 idx<-readRDS(file.path(dirs[['baseline']],'matrix_index.rds'));d<-as.data.table(idx$demand);cands<-as.data.table(readRDS(P('06_Optimization','Phase10B_Candidates','mobile_routing_candidates.rds')))
 stopifnot(nrow(d)==51014L,sum(d$match_1km)==31002L,abs(sum(d$population)-34746370)<1,nrow(cands)==3581L,!anyDuplicated(cands$candidate_id),!anyDuplicated(cands$vertex_id),all(cands$candidate_eligible),all(cands$connector_m>=0&cands$connector_m<=1000))
 stopifnot(all(as.character(cands$node_id)==as.character(v$node_id[cands$vertex_id])),all(cands$weak_component==v$weak_component[cands$vertex_id]))
 targets<-as.integer(idx$targets);sources<-as.integer(cands$vertex_id);reuse<-match(sources,idx$sources);stopifnot(sum(!is.na(reuse))==1224L,sum(is.na(reuse))==2357L)
 dr<-which(d$match_1km);target_rows<-split(dr,d$target_index[dr]);stopifnot(all(targets[d$target_index[dr]]==d$vertex_id[dr]))
 # Full demand row indexing is retained, including unmatched rows (all zero in coverage).
 saveRDS(list(demand=d,candidates=cands,targets=targets,sources=sources,threshold_minutes=c(30,60,120),connector_speed_kmh=4,bound_seconds=7200),file.path(out,'mobile_matrix_index.rds'))
 paths<-file.path(out,'mobile_matrix_index.rds');inv<-list();diagnostics<-list();regional<-list();tests_all<-list();batch_paths<-list();coverage_paths<-list()
 atomic<-function(x,p){tmp<-paste0(p,'.tmp');saveRDS(x,tmp,compress=FALSE);if(file.exists(p))stop('Refusing to overwrite checkpoint: ',p);stopifnot(file.rename(tmp,p))}
 eq<-function(x,y)all((is.infinite(x)&is.infinite(y))|(is.finite(x)&is.finite(y)&abs(x-y)<=1e-6*pmax(1,abs(x),abs(y))))
 batch<-split(seq_along(sources),ceiling(seq_along(sources)/25L))
 for(speed in names(dirs)){
  cat('\nMOBILE',toupper(speed),'\n');dest<-file.path(out,toupper(speed));dir.create(dest,showWarnings=FALSE);cp<-file.path(dest,'Checkpoints');dir.create(cp,showWarnings=FALSE)
  zidx<-readRDS(file.path(dirs[[speed]],'matrix_index.rds'));stopifnot(zidx$network=='CORE_PRIMARY',zidx$speed==speed,zidx$bound_seconds==7200,identical(zidx$targets,idx$targets),identical(zidx$sources,idx$sources),identical(zidx$demand$demand_id,d$demand_id),identical(zidx$demand$target_index,d$target_index),identical(zidx$demand$match_1km,d$match_1km),identical(zidx$demand$connector_m,d$connector_m))
  w<-cost[[paste0(speed,'_seconds')]];sig<-digest(list(old=old,speed=speed,targets=targets,sources=sources,candidates=cands,version='10C_v1'),algo='sha256')
  cache<-vector('list',length(zidx$sources));seen<-rep(FALSE,length(cache))
  for(b in zidx$batch_files){z<-readRDS(file.path(dirs[[speed]],'Checkpoints',b));stopifnot(identical(z$signature,zidx$signature),length(z$columns)==length(z$source_indices),!any(seen[z$source_indices]));for(k in seq_along(z$source_indices))cache[[z$source_indices[k]]]<-z$columns[[k]];seen[z$source_indices]<-TRUE};stopifnot(all(seen))
  # Test new and reused sources against forward queries and direct reverse queries.
  set.seed(20261126);sample_sources<-c(sample(which(is.na(reuse)),8),sample(which(!is.na(reuse)),8));tt<-list()
  for(j in sample_sources){s<-sources[j];near<-order((v$easting[targets]-v$easting[s])^2+(v$northing[targets]-v$northing[s])^2)[1:4];ti<-unique(c(targets[near],sample(targets,2),s));r<-router_query(gr,s,w,7200,as.integer(ti));fw<-vapply(ti,function(t)router_query(gf,as.integer(t),w,7200,s)[1],numeric(1));stopifnot(eq(r,fw),r[match(s,ti)]==0);if(!is.na(reuse[j])){x<-cache[[reuse[j]]];m<-match(match(ti,targets),x$i);ref<-rep(Inf,length(ti));ref[!is.na(m)]<-x$seconds[m[!is.na(m)]];ok<-ti%in%targets;stopifnot(eq(ref[ok],r[ok]))};tt[[length(tt)+1L]]<-data.table(speed=speed,candidate_id=cands$candidate_id[j],source_vertex=s,target_vertex=ti,reverse_seconds=r,forward_seconds=fw,reused=!is.na(reuse[j]))}
  tests_all[[speed]]<-rbindlist(tt)
  check<-function(z,ix){stopifnot(identical(z$signature,sig),identical(z$source_indices,as.integer(ix)),length(z$columns)==length(ix));for(k in seq_along(ix)){x<-z$columns[[k]];stopifnot(is.integer(x$i),length(x$i)==length(x$seconds),!anyDuplicated(x$i),all(x$i>=1L&x$i<=length(targets)),all(is.finite(x$seconds)&x$seconds>=0&x$seconds<=7200),all(v$weak_component[targets[x$i]]==v$weak_component[sources[ix[k]]])) ;if(!is.na(reuse[ix[k]]))stopifnot(identical(x,cache[[reuse[ix[k]]]]))};TRUE}
  bp<-character(length(batch));counts<-integer(length(sources));pair_i<-vector('list',length(sources));pair_t<-vector('list',length(sources));best<-rep(Inf,nrow(d))
  for(b in seq_along(batch)){ix<-as.integer(batch[[b]]);p<-file.path(cp,sprintf('batch_%04d.rds',b));bp[b]<-p
   if(file.exists(p)){z<-readRDS(p);check(z,ix)}else{cols<-lapply(ix,function(j){if(!is.na(reuse[j]))return(cache[[reuse[j]]]);x<-router_query(gr,sources[j],w,7200,targets);keep<-which(is.finite(x));list(i=as.integer(keep),seconds=as.numeric(x[keep]))});z<-list(signature=sig,source_indices=ix,columns=cols);check(z,ix);atomic(z,p)}
   for(k in seq_along(ix)){j<-ix[k];x<-z$columns[[k]];counts[j]<-length(x$i);groups<-target_rows[as.character(x$i)];ng<-lengths(groups);rr<-as.integer(unlist(groups,use.names=FALSE));ts<-rep(x$seconds,ng)+3.6*(d$connector_m[rr]+cands$connector_m[j])/4;keep<-which(ts<=7200);rr<-rr[keep];ts<-ts[keep];stopifnot(!anyDuplicated(rr),all(d$match_1km[rr]));pair_i[[j]]<-rr;pair_t[[j]]<-ts;best[rr]<-pmin(best[rr],ts)}
   if(b%%10==0||b==length(batch))cat('Completed or recovered batch',b,'/',length(batch),'\n');flush.console()
  }
  batch_paths[[speed]]<-bp;paths<-c(paths,bp);rm(cache);gc()
  cov<-list();for(h in c(30,60,120)){rows<-lapply(seq_along(sources),function(j)pair_i[[j]][pair_t[[j]]<=h*60]);lens<-lengths(rows);B<-sparseMatrix(i=as.integer(unlist(rows,use.names=FALSE)),j=rep(seq_along(sources),lens),dims=c(nrow(d),nrow(cands)),dimnames=list(as.character(d$demand_id),as.character(cands$candidate_id)));stopifnot(all(Matrix::rowSums(B)[!d$match_1km]==0),identical(as.logical(Matrix::rowSums(B)>0),best<=h*60));cov[[as.character(h)]]<-B
   diagnostics[[length(diagnostics)+1L]]<-data.table(speed=speed,threshold_minutes=h,population=sum(d$population),covered_population=sum(d$population[best<=h*60]),covered_pct=100*sum(d$population[best<=h*60])/sum(d$population),coverage_pairs=sum(lens),candidates_with_coverage=sum(lens>0))
   regional[[length(regional)+1L]]<-d[,.(population=sum(population),covered_population=sum(population[best[.I]<=h*60])),by=region_group][,`:=`(speed=speed,threshold_minutes=h,covered_pct=100*covered_population/population)]
  }
  p<-file.path(dest,'coverage_matrices.rds');saveRDS(cov,p);coverage_paths[[speed]]<-p;paths<-c(paths,p);p<-file.path(dest,'source_summary.csv');fwrite(data.table(candidate_id=cands$candidate_id,vertex_id=sources,reused=!is.na(reuse),finite_network_pairs=counts),p);paths<-c(paths,p)
  inv[[speed]]<-data.table(speed=speed,candidates=length(sources),reused=sum(!is.na(reuse)),new_searches=sum(is.na(reuse)),batches=length(bp),finite_network_pairs=sum(as.double(counts)))
  rm(cov,B,rows,pair_i,pair_t);gc()
 }
 rm(gr,gf,cost);gc()
 # Exhaustive ordering on network travel times and coverage matrix nesting.
 compare<-function(slow,fast){n<-0;missing<-0;viol<-0;for(b in seq_along(batch)){x<-readRDS(batch_paths[[slow]][b]);y<-readRDS(batch_paths[[fast]][b]);stopifnot(identical(x$source_indices,y$source_indices));for(k in seq_along(x$columns)){u<-x$columns[[k]];z<-y$columns[[k]];m<-match(u$i,z$i);ok<-!is.na(m);n<-n+length(m);missing<-missing+sum(!ok);viol<-viol+sum(z$seconds[m[ok]]>u$seconds[ok]+1e-6*pmax(1,u$seconds[ok]))}};data.table(slower=slow,faster=fast,compared_pairs=n,missing_faster_pairs=missing,violations=viol)}
 ordercheck<-rbindlist(list(compare('slow','baseline'),compare('baseline','favorable')));stopifnot(all(ordercheck$missing_faster_pairs==0),all(ordercheck$violations==0))
 subset_check<-function(A,B){stopifnot(identical(dimnames(A),dimnames(B)));nnzero(A & B)==nnzero(A)}
 for(s in names(dirs)){q<-readRDS(coverage_paths[[s]]);stopifnot(subset_check(q[['30']],q[['60']]),subset_check(q[['60']],q[['120']]))};rm(q);gc()
 for(s in c('slow','baseline')){q<-readRDS(coverage_paths[[s]]);r<-readRDS(coverage_paths[[if(s=='slow')'baseline' else 'favorable']]);stopifnot(all(vapply(names(q),function(h)subset_check(q[[h]],r[[h]]),logical(1))));rm(q,r);gc()}
 inventory<-rbindlist(inv);national<-rbindlist(diagnostics);reg<-rbindlist(regional);tests<-rbindlist(tests_all);rec<-reg[,.(pop=sum(population),covered=sum(covered_population)),by=.(speed,threshold_minutes)];rec<-merge(rec,national,by=c('speed','threshold_minutes'));stopifnot(nrow(rec)==9L,all(abs(rec$pop-rec$population)<1e-5),all(abs(rec$covered-rec$covered_population)<1e-5))
 gate<-data.table(check=c('Prior manifests unchanged','Candidate identity and graph mapping','All national demand retained','Three speed matrices completed','Compatible existing routes reused exactly','All new sources processed','Sample forward reverse equivalence','Full speed ordering','Coverage threshold and speed nesting','National regional reconciliation'),passed=c(all(hash(P(old$relative_path))==old$SHA256),TRUE,nrow(d)==51014L,nrow(inventory)==3L,TRUE,all(inventory$new_searches==2357L),TRUE,all(ordercheck$violations==0&ordercheck$missing_faster_pairs==0),TRUE,nrow(rec)==9L));stopifnot(all(gate$passed))
 outputs<-list('10_Tables/phase10C_mobile_matrix_inventory.csv'=inventory,'10_Tables/phase10C_mobile_all_site_coverage.csv'=national,'10_Tables/phase10C_mobile_regional_all_site_coverage.csv'=reg,'03_Data_Audit/phase10C_reverse_route_tests.csv'=tests,'03_Data_Audit/phase10C_speed_order_checks.csv'=ordercheck,'03_Data_Audit/phase10C_quality_gate.csv'=gate,'12_Reproducibility/phase10C_modelling_assumptions.csv'=data.table(item=c('Sites','Transport','Coverage','Capacity','Unmatched'),treatment=c('Hypothetical hosts; physical feasibility not verified','Core road network; three hypothetical speed profiles; compiled restrictions only','Patient travel; 1km connectors at 4km/h; 30/60/120 minutes; all-site diagnostic not fleet allocation','Equal unlimited service coverage assumed; no operational scheduling or costs','All demand retained; unmatched rows zero in modelled coverage, actual access unknown'))))
 for(n in names(outputs)){fwrite(outputs[[n]],P(n));paths<-c(paths,P(n))};sp<-P('13_R_Scripts','phase10C_complete.R');writeLines(c('phase10C_run <-',deparse(phase10C_run,width.cutoff=500L),'phase10C_results <- phase10C_run()'),sp);paths<-c(paths,sp)
 paths<-sort(unique(normalizePath(paths,winslash='/',mustWork=TRUE)));man<-data.table(relative_path=substring(paths,nchar(root)+2),SHA256=hash(paths),size_bytes=file.info(paths)$size);fwrite(man,P('12_Reproducibility','phase10C_output_checksum_manifest.csv'));man[,verified:=hash(P(relative_path))==SHA256];stopifnot(all(man$verified));fwrite(man,P('12_Reproducibility','phase10C_checksum_recheck.csv'))
 print(inventory);print(national);print(ordercheck);print(gate);cat('PHASE 10C MOBILE MATRICES PASS\nChecksums:',sum(man$verified),'/',nrow(man),'\nElapsed seconds:',as.numeric(difftime(Sys.time(),started,units='secs')),'\nALL-SITE COVERAGE IS NOT A FLEET OPTIMIZATION RESULT\n');invisible(list(inventory=inventory,national=national,regional=reg,quality=gate))
}
phase10C_results <- phase10C_run()
